import{z as s,x as A,o as e,c as h,q as n,j as i,D as a,d as t,s as o,S as m,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"掩模误差增强因子 MEEF","description":"","frontmatter":{"title":"掩模误差增强因子 MEEF","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/meef.md","filePath":"litho/meef.md","lastUpdated":1791063341000}'),p={name:"litho/meef.md"};function D(d,E,M,B,F,C){const l=A("Mermaid");return e(),h("div",null,[E[2]||(E[2]=n('<h1 id="掩模误差增强因子-meef" tabindex="-1">掩模误差增强因子 MEEF <a class="header-anchor" href="#掩模误差增强因子-meef" aria-label="Permalink to &quot;掩模误差增强因子 MEEF&quot;">​</a></h1><div class="epigraph"><p>剂量轴已经用 EL 量过了；掩模线宽若再漂一纳米，晶圆上往往漂得不止缩比后的那一纳米。</p><footer>—— 据 Schellenberg 对 RET / 掩模误差因子的讨论，以及 Wong, Resolution Enhancement Techniques in Optical Lithography</footer></div><p><a href="/litho/exposure-latitude">上一课</a>把 \\(k_1\\) 窗口的剂量轴写成 EL。缺口是另一条误差通道：掩模 CD 并不等于设计值，而低通成像会把这点误差<strong>放大</strong>到晶圆。本课钉掩模误差增强因子</p> \\[\\mathrm{MEEF}=\\frac{\\partial\\mathrm{CD}_\\mathrm{wafer}}{\\partial(\\mathrm{CD}_\\mathrm{mask}/M)}, \\]<p>\\(M\\) 是投影缩比（常见 \\(4\\times\\)，即像方看到的掩模 CD 已除过 \\(M\\)）。光学邻近如何按邻域系统地偏置，留给后课 OPE。不要把 MEEF 写成又一个 \\(k_1\\)：它是导数，不是分辨率工作点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EL 问的是剂量还能漂多少。掩模厂的 CD 均匀性、写入噪声、蚀刻偏置是另一笔预算。若成像是理想缩放，晶圆 \\(\\Delta\\mathrm{CD}\\) 等于掩模 \\(\\Delta\\mathrm{CD}/M\\)，MEEF\\(=1\\)。靠近截止时，空中像斜坡变缓，掩模开宽一点，进瞳的级权重非线性地变，晶圆 CD 动得更凶，MEEF\\(\\gt 1\\)。缺口因此是这条导数，而不是再报一次 EL。</p><p>接触孔、线端、SRAF 附近往往比一维密栅更差：二维频谱对开口尺寸更敏感。只量线栅 MEEF 会低估层风险。</p><p><span class="marginnote">MEEF 一句话翻译：&quot;掩模做错 1 nm（折算缩比后），晶圆跟着错几纳米&quot;。MEEF=1 是理想复印机；MEEF=3 意味着掩模厂 3 nm 的误差，在晶圆上要按 9 nm 记账——误差被&quot;放大器&quot;加了两次倍。</span></p><h3 id="缩比必须写进分母" tabindex="-1">缩比必须写进分母 <a class="header-anchor" href="#缩比必须写进分母" aria-label="Permalink to &quot;缩比必须写进分母&quot;">​</a></h3><p>口语有时把掩模纳米直接去除晶圆纳米，忘掉 \\(4\\times\\)。那样会把 MEEF 虚高四倍。定义必须用<strong>像方等效</strong>的掩模 CD，即 \\(\\mathrm{CD}_\\mathrm{mask}/M\\)。OPC 碎片的移动量也按这一侧比较。</p><p><span class="marginnote">MEEF 随节距、占空比、照明和偏振变。报一个层的「MEEF=2」而不写图形，与报 \\(k_1\\) 不写层别同样无意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>仿真：把掩模目标边整体外推或内缩一小段，再算晶圆 CD（阈值或胶模型），取差商。硅片：用刻意偏置的掩模模块或写入剂量矩阵，回归斜率。规格上，掩模 CD 公差 \\(\\times\\) MEEF 必须小于晶圆 CD 预算里分给掩模的那一截——其余分给 EL、焦深、计量。</p><p>SMO / OPC 若只最大化 NILS 或 EL，可能把 MEEF 抬到掩模厂接不住。因此增强因子必须进目标函数，与上一课的剂量轴并列，而不是优化完再惊讶。</p><h3 id="与-nils、el-的关系" tabindex="-1">与 NILS、EL 的关系 <a class="header-anchor" href="#与-nils、el-的关系" aria-label="Permalink to &quot;与 NILS、EL 的关系&quot;">​</a></h3><p>NILS 低，边对<strong>任何</strong>让相对阈值或频谱微变的量都敏感：剂量是 EL，开口宽度是 MEEF。两者同源（缓坡），不是同一个数：改变剂量是乘在 \\(I\\) 上；改变掩模是改 \\(T(\\mathbf{f})\\)，再经 TCC 双线性。相移膜、助条让 \\(T\\) 的导数更绕，MEEF 可以局部很大甚至变号。</p><p><span class="marginnote">MEEF\\(\\lt 1\\) 偶尔出现在某些孤立图形或过修正区，不表示「掩模越随便越好」：均匀性仍在，只是斜率小于缩放。</span></p>',18)),(e(),i(m,null,{default:a(()=>[o(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%20CD%20%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20RED%5B%22%E9%99%A4%E4%BB%A5%E7%BC%A9%E6%AF%94%20M%22%5D%0A%20%20RED%20--%3E%20MEEF%5B%22MEEF%20%3D%20dCDw%20%2F%20dCDm%2Ceq%22%5D%0A%20%20ILS%5B%22%E7%BC%93%E5%9D%A1%20%2F%20%E4%BD%8E%20NILS%22%5D%20--%3E%20MEEF%0A%20%20MEEF%20--%3E%20BUD%5B%22%E6%99%B6%E5%9C%86%20CD%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20EL%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%20EL%22%5D%20--%3E%20BUD%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,"物体频谱对开口宽度的导数，经光瞳低通之后，像面斜坡对开口的响应可以大于几何缩放。\\(k_1\\) 越低、一级越贴瞳边，这份非线性越强——与窗口课「靠近地板时二维先死」一致，本课只把它读成掩模公差。TCC 双线性意味着邻线也进导数：邻近图形的掩模误差会串到本线 CD，这是 OPE 课的系统版；MEEF 通常先报「本图形均匀偏置」的对角项。",-1)),(e(),i(m,null,{default:a(()=>[o(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20NILS%5B%22%E4%BD%8E%20NILS%3A%20%E8%BE%B9%E6%B2%BF%E6%96%9C%E5%9D%A1%E7%BC%93%22%5D%20--%3E%20DOSE%5B%22%E9%80%9A%E9%81%93%E4%B8%80%3A%20%E5%8A%A8%E5%89%82%E9%87%8F%22%5D%0A%20%20NILS%20--%3E%20MASK%5B%22%E9%80%9A%E9%81%93%E4%BA%8C%3A%20%E5%8A%A8%E6%8E%A9%E6%A8%A1%E5%BC%80%E5%8F%A3%22%5D%0A%20%20DOSE%20--%3E%20EL%5B%22CD%20%E5%8A%A8%E5%BE%97%E5%A4%9A%3A%20EL%20%E5%8F%98%E7%AA%84%22%5D%0A%20%20MASK%20--%3E%20MEEF%5B%22CD%20%E5%8A%A8%E5%BE%97%E6%9B%B4%E5%A4%9A%3A%20MEEF%20%E5%A4%A7%E4%BA%8E%201%22%5D%0A%20%20EL%20--%3E%20BUD%5B%22%E5%90%8C%E4%B8%80%E7%AA%97%E5%8F%A3%E9%A2%84%E7%AE%97%22%5D%0A%20%20MEEF%20--%3E%20BUD%0A%20%20BUD%20--%3E%20RULE%5B%22%E6%8E%A9%E6%A8%A1%E5%85%AC%E5%B7%AE%20x%20MEEF%20%E9%A1%BB%E5%B0%8F%E4%BA%8E%E9%A2%84%E7%AE%97%E4%BB%BD%E9%A2%9D%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">预算怎么算：若晶圆 CD 预算 4 nm、分给掩模 1.5 nm，这一层 MEEF=3，则掩模 CD 公差最多 1.5 除以 3 得 0.5 nm（像方等效）。掩模厂接不住 0.5 nm，就得回头改照明或 OPC 目标，而不是硬压掩模规格。</span></p><p><span class="marginnote">常见误区是以为剂量宽（EL 大）就能兜住掩模误差。两条通道不同：剂量是全场乘一个系数，补偿不了掩模场内的空间相关误差——左边线粗右边线细这种错，加不加剂量都抹不平。</span></p><p>矢量 TM 把 NILS 再削一截，MEEF 往往更差。控偏振可以同时改善 EL 与 MEEF，仍要分别验收。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到掩模公差能否支撑这一层，先问 MEEF，再乘掩模厂能力。说到 OPC，边移动的收益必须用 MEEF 加权，避免在高增强区猛修。OPE 是系统邻近偏置，MEEF 是误差放大；后课不要把两个名字写成一个旋钮。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MEEF 不含套刻、不含 EUV 掩模 3D 阴影的全部取向差——除非仿真已把它们算进 \\(\\mathrm{CD}_\\mathrm{wafer}\\)。也不要把写入器的纳米数直接当 \\(\\mathrm{CD}_\\mathrm{mask}\\)：测量偏置与 tone 要声明。本课不编造未公开的掩模厂纳米指标或某代节点「MEEF 上限」。</p><p>EL 再宽也买不回 MEEF：剂量均匀补偿不了掩模场内的空间相关误差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{MEEF}=\\partial\\mathrm{CD}_\\mathrm{wafer}/\\partial(\\mathrm{CD}_\\mathrm{mask}/M)\\)，分母必须是像方等效掩模 CD。</li><li>低通、低 NILS 时 MEEF 常大于 1；孔与线端往往更差。</li><li>与 EL 同源（缓坡）但通道不同：一个改剂量，一个改物频谱。</li><li>RET / OPC 必须把 MEEF 放进目标，否则窗口数字不可制造。</li><li>后课 OPE 谈系统邻近偏置，不替代本课的误差放大。</li><li>出处：Schellenberg 对 RET 与掩模误差因子；Wong, <em>Resolution Enhancement Techniques in Optical Lithography</em>；Mack / Levinson 的产线定义。</li></ul>',10))])}const f=s(p,[["render",D]]);export{u as __pageData,f as default};
